export const quizTopics=[{"id":"aves","title":"Pájaros","heading":"Aves que nos rodean","description":"Nidos, plumajes y curiosidades de nuestras aves.","questions":[{"id":"aves-01","question":"¿Qué caza al vuelo el abejaruco europeo?","options":["Insectos como abejas y avispas","Peces pequeños","Semillas de cardo"],"answer":0,"explanation":"Captura insectos en vuelo.","source":"https://seo.org/ave/abejaruco-europeo/"},{"id":"aves-02","question":"¿Dónde excava su nido el abejaruco europeo?","options":["En una plataforma de ramas","En una caja nido","En un talud arenoso"],"answer":2,"explanation":"Excava una galería en taludes arenosos.","source":"https://seo.org/ave/abejaruco-europeo/"},{"id":"aves-03","question":"¿Qué ave suele aceptar cajas nido para criar?","options":["El abejaruco europeo","El carbonero común","La cigüeña blanca"],"answer":1,"explanation":"El carbonero anida en cavidades y acepta cajas nido.","source":"https://seo.org/ave/carbonero-comun/"},{"id":"aves-04","question":"¿De qué color son las mejillas del carbonero común adulto?","options":["Blancas","Rojas","Azules"],"answer":0,"explanation":"Las mejillas blancas contrastan con su cabeza negra.","source":"https://seo.org/ave/carbonero-comun/"},{"id":"aves-05","question":"¿Cómo se llama el sonido de la cigüeña blanca al golpear el pico?","options":["Trino","Tamborileo","Crotoreo"],"answer":2,"explanation":"El crotoreo es el característico golpeteo del pico.","source":"https://seo.org/ave/ciguena-blanca/"},{"id":"aves-06","question":"¿Cómo suele volar la cigüeña blanca?","options":["Con las patas recogidas","Con cuello y patas extendidos","Con el cuello recogido"],"answer":1,"explanation":"En vuelo lleva cuello y patas estirados.","source":"https://seo.org/ave/ciguena-blanca/"},{"id":"aves-07","question":"¿Con qué construye principalmente su nido la golondrina común?","options":["Barro","Piedrecillas sueltas","Astillas de madera"],"answer":0,"explanation":"Construye un nido abierto de barro en forma de taza.","source":"https://seo.org/ave/golondrina-comun/"},{"id":"aves-08","question":"¿Cómo es la cola de la golondrina común?","options":["Redondeada y corta","Cuadrada y ancha","Larga y ahorquillada"],"answer":2,"explanation":"Destaca su cola larga y ahorquillada.","source":"https://seo.org/ave/golondrina-comun/"},{"id":"aves-09","question":"¿Qué zona anaranjada destaca en el petirrojo adulto?","options":["El vientre y las patas","La cara y el pecho","Las alas y la cola"],"answer":1,"explanation":"Su mancha anaranjada ocupa la cara y el pecho.","source":"https://seo.org/ave/petirrojo-europeo/"},{"id":"aves-10","question":"¿Cómo son los plumajes del macho y la hembra de petirrojo adulto?","options":["Muy parecidos","Solo el macho tiene pecho naranja","Solo la hembra tiene pecho naranja"],"answer":0,"explanation":"Machos y hembras presentan plumajes similares.","source":"https://seo.org/ave/petirrojo-europeo/"},{"id":"aves-11","question":"¿Cómo obtiene gran parte de su alimento el vencejo común?","options":["Buscando semillas en el suelo","Pescando desde una rama","Capturando insectos mientras vuela"],"answer":2,"explanation":"El vencejo captura insectos en vuelo.","source":"https://seo.org/ave/vencejo-comun/"},{"id":"aves-12","question":"¿Dónde puede criar el vencejo común en poblaciones españolas?","options":["En galerías excavadas en arena","En huecos de edificios","En nidos flotantes"],"answer":1,"explanation":"Suele aprovechar huecos de construcciones.","source":"https://seo.org/ave/vencejo-comun/"},{"id":"aves-13","question":"¿Cómo es el nido del mito común?","options":["Cerrado, con una pequeña entrada","Una taza abierta en el suelo","Una plataforma abierta de ramas"],"answer":0,"explanation":"Construye un nido cerrado con un pequeño agujero de entrada.","source":"https://seo.org/ave/mito-comun/"},{"id":"aves-14","question":"¿Dónde construye el nido el pico picapinos?","options":["En una taza de barro bajo un tejado","En un túnel excavado en arena","En una cavidad excavada en la madera"],"answer":2,"explanation":"Excava una cavidad en un tronco para criar.","source":"https://seo.org/ave/pico-picapinos/"},{"id":"aves-15","question":"¿Qué busca el pico picapinos bajo la corteza?","options":["Pequeños peces","Larvas de insectos","Semillas de cardo"],"answer":1,"explanation":"Busca larvas de insectos en la madera y bajo la corteza.","source":"https://seo.org/ave/pico-picapinos/"},{"id":"aves-16","question":"¿Qué semillas son un alimento característico del jilguero europeo?","options":["Las de los cardos","Las de los pinos","Las de los robles"],"answer":0,"explanation":"Se alimenta de semillas de cardos y otras plantas.","source":"https://seo.org/ave/jilguero-europeo/"},{"id":"aves-17","question":"¿De qué color es la máscara facial del jilguero adulto?","options":["Azul","Verde","Roja"],"answer":2,"explanation":"La máscara roja es una de sus marcas distintivas.","source":"https://seo.org/ave/jilguero-europeo/"},{"id":"aves-18","question":"¿Qué hace el cuco común con sus huevos?","options":["Los coloca en un nido flotante propio","Los deposita en nidos de otras especies","Los entierra en arena"],"answer":1,"explanation":"Practica el parasitismo de cría y pone huevos en nidos de otras aves.","source":"https://seo.org/ave/cuco-comun/"},{"id":"aves-19","question":"¿Cómo suele pescar el martín pescador común?","options":["Se lanza al agua desde un posadero","Persigue peces andando por la orilla","Filtra el agua con el pico"],"answer":0,"explanation":"Se lanza desde un posadero para capturar peces.","source":"https://seo.org/ave/martin-pescador-comun/"},{"id":"aves-20","question":"¿Dónde anida normalmente el martín pescador común?","options":["En una copa de barro bajo un alero","En una cesta de ramas en un árbol","Al fondo de un túnel excavado en un talud"],"answer":2,"explanation":"Excava un túnel en un talud para llegar a la cámara de cría.","source":"https://seo.org/ave/martin-pescador-comun/"}],"icon":"sprout"},{"id":"carpinteria","title":"Carpintería","heading":"El taller de carpintería","description":"Herramientas y técnicas para trabajar la madera.","questions":[{"id":"carpinteria-01","question":"¿Qué herramienta comprueba si dos cantos forman un ángulo recto?","options":["La escuadra","El gramil","La escofina"],"answer":0,"explanation":"La escuadra permite comprobar y trazar ángulos rectos.","source":"https://www.ou.edu/content/dam/gibbs/documents/explore/centers-and-labs/creating_making-lab/creating-making-lab-safety-manual.pdf"},{"id":"carpinteria-02","question":"¿Cuántos grados tiene el ángulo recto de una escuadra?","options":["45 grados","60 grados","90 grados"],"answer":2,"explanation":"Un ángulo recto mide 90 grados.","source":"https://www.ou.edu/content/dam/gibbs/documents/explore/centers-and-labs/creating_making-lab/creating-making-lab-safety-manual.pdf"},{"id":"carpinteria-03","question":"¿Qué herramienta ajustable permite copiar y trasladar distintos ángulos?","options":["El cepillo de mano","La falsa escuadra","La plomada"],"answer":1,"explanation":"La falsa escuadra permite reproducir distintos ángulos.","source":"https://www.ou.edu/content/dam/gibbs/documents/explore/centers-and-labs/creating_making-lab/creating-making-lab-safety-manual.pdf"},{"id":"carpinteria-04","question":"¿Qué herramienta marca una línea a distancia constante del borde de una tabla?","options":["El gramil","La gubia","El serrucho"],"answer":0,"explanation":"El gramil se apoya en el borde para trazar una paralela.","source":"https://www.ou.edu/content/dam/gibbs/documents/explore/centers-and-labs/creating_making-lab/creating-making-lab-safety-manual.pdf"},{"id":"carpinteria-05","question":"¿Qué herramienta permite trazar una circunferencia sobre madera?","options":["La plomada","El formón","El compás"],"answer":2,"explanation":"Con un compás se marcan arcos y circunferencias.","source":"https://www.ou.edu/content/dam/gibbs/documents/explore/centers-and-labs/creating_making-lab/creating-making-lab-safety-manual.pdf"},{"id":"carpinteria-06","question":"¿Qué instrumento retráctil mide la longitud de una tabla?","options":["La plomada","El flexómetro","La falsa escuadra"],"answer":1,"explanation":"El flexómetro es una cinta flexible que se recoge en una carcasa.","source":"https://cld.ca.uky.edu/sites/cld.ca.uky.edu/files/Ag.%20Mechanics%20Shop%20Book.pdf"},{"id":"carpinteria-07","question":"¿Qué instrumento usa un peso suspendido para indicar la vertical?","options":["La plomada","El gramil","La escuadra de inglete"],"answer":0,"explanation":"La plomada señala la vertical mediante un peso suspendido.","source":"https://fog.ccsf.edu/~doconnel/handtools.htm"},{"id":"carpinteria-08","question":"¿Qué instrumento con burbuja ayuda a comprobar la horizontalidad?","options":["El calibre de espesores","La escofina","El nivel"],"answer":2,"explanation":"El nivel de burbuja permite comprobar la horizontalidad.","source":"https://www.ou.edu/content/dam/gibbs/documents/explore/centers-and-labs/creating_making-lab/creating-making-lab-safety-manual.pdf"},{"id":"carpinteria-09","question":"¿Qué herramienta alisa la madera arrancando virutas con una cuchilla?","options":["El compás","El cepillo de carpintero","La plomada"],"answer":1,"explanation":"El cepillo corta virutas para rebajar y alisar.","source":"https://support.stanleytools.com/hc/en-us/article_attachments/360012493557"},{"id":"carpinteria-10","question":"¿Qué cepillo es apropiado para trabajar la madera a testa?","options":["El cepillo de testa","El gramil","La falsa escuadra"],"answer":0,"explanation":"El cepillo de testa está pensado para trabajar el extremo de una pieza.","source":"https://support.stanleytools.com/hc/en-us/article_attachments/360012493557"},{"id":"carpinteria-11","question":"En un cepillo, ¿qué pieza corta la madera para formar virutas?","options":["La suela","El mango","La cuchilla"],"answer":2,"explanation":"La cuchilla afilada corta la madera al pasar el cepillo.","source":"https://support.stanleytools.com/hc/en-us/article_attachments/360012493557"},{"id":"carpinteria-12","question":"¿Para qué se usa un serrucho de corte transversal?","options":["Para comprobar ángulos","Para cortar atravesando las fibras","Para trazar círculos"],"answer":1,"explanation":"Está diseñado para cortar a través de la fibra.","source":"https://extension.oregonstate.edu/sites/extd8/files/documents/4-h4421.pdf"},{"id":"carpinteria-13","question":"¿Qué caracteriza a una sierra de costilla?","options":["Un refuerzo rígido en el lomo","Una hoja circular que gira","Un peso suspendido de una cuerda"],"answer":0,"explanation":"Tiene dientes finos y un lomo rígido para cortes precisos.","source":"https://cld.ca.uky.edu/sites/cld.ca.uky.edu/files/Ag.%20Mechanics%20Shop%20Book.pdf"},{"id":"carpinteria-14","question":"¿Qué sierra manual de arco y hoja estrecha permite cortes curvos?","options":["El serrucho de costilla","La sierra circular de mesa","La sierra de marquetería"],"answer":2,"explanation":"La sierra de marquetería permite seguir curvas en madera.","source":"https://www.stanleytools.com/product/15-104/coping-saw"},{"id":"carpinteria-15","question":"¿Qué herramienta sirve para rebajar madera o abrir una caja para una unión?","options":["El metro","El formón","La plomada"],"answer":1,"explanation":"El formón permite cortar y retirar madera, por ejemplo para crear un hueco.","source":"https://labs.utdallas.edu/projectworkshop/chisel/"},{"id":"carpinteria-16","question":"¿Qué herramienta de talla tiene un filo curvo para hacer canales o cavidades?","options":["La gubia","La escuadra","El calibre"],"answer":0,"explanation":"La gubia tiene filo curvo para tallar superficies cóncavas.","source":"https://fog.ccsf.edu/~doconnel/handtools.htm"},{"id":"carpinteria-17","question":"¿Para qué sirve una escofina para madera?","options":["Para medir longitudes","Para señalar la vertical","Para desbastar y dar forma"],"answer":2,"explanation":"La escofina se emplea para retirar material y dar forma.","source":"https://www.stanleytools.com/product/21-113/8-double-cut-rasp-cut-4-1-file"},{"id":"carpinteria-18","question":"¿Qué material abrasivo se usa para suavizar una superficie de madera?","options":["El hilo de la plomada","El papel de lija","La cinta métrica"],"answer":1,"explanation":"La lija utiliza granos abrasivos para suavizar superficies.","source":"https://extension.oregonstate.edu/sites/extd8/files/documents/4-h4421.pdf"},{"id":"carpinteria-19","question":"¿Para qué sirve un sargento de carpintero?","options":["Para sujetar piezas mediante presión","Para medir el ángulo de un corte","Para trazar circunferencias"],"answer":0,"explanation":"Mantiene sujetas las piezas mientras se trabaja o pega.","source":"https://labs.utdallas.edu/projectworkshop/chisel/"},{"id":"carpinteria-20","question":"¿Qué accesorio de un taladro se usa para hacer agujeros?","options":["La hoja de serrucho","La cuchilla del cepillo","La broca"],"answer":2,"explanation":"La broca perfora el material al girar.","source":"https://extension.oregonstate.edu/sites/extd8/files/documents/4-h4421.pdf"}],"icon":"cup"},{"id":"taxi","title":"El mundo del taxi","heading":"Al volante del taxi","description":"El oficio, la accesibilidad y taxis de distintas ciudades.","questions":[{"id":"taxi-01","question":"¿Para qué sirve el taxímetro?","options":["Para calcular e indicar el importe de un viaje","Para indicar la presión de los neumáticos","Para calcular la carga de la batería"],"answer":0,"explanation":"El taxímetro calcula e indica el importe del servicio según las condiciones de la tarifa.","source":"https://boe.es/buscar/act.php?id=BOE-A-2020-2573"},{"id":"taxi-02","question":"En un taxímetro, ¿qué es la bajada de bandera?","options":["Un descuento por viajar de noche","El importe inicial del servicio","La distancia máxima de un viaje"],"answer":1,"explanation":"La bajada de bandera es la cantidad inicial indicada por el taxímetro.","source":"https://boe.es/buscar/act.php?id=BOE-A-2020-2573"},{"id":"taxi-03","question":"Además de la distancia recorrida, ¿qué magnitud puede intervenir en el cálculo del taxímetro?","options":["La altura sobre el nivel del mar","El número de maletas del conductor","El tiempo transcurrido"],"answer":2,"explanation":"El cálculo puede basarse en la distancia recorrida y el tiempo transcurrido, según las condiciones aplicables.","source":"https://boe.es/buscar/act.php?id=BOE-A-2020-2573"},{"id":"taxi-04-v2","question":"En Londres, ¿cómo debe contratarse un vehículo de private hire, como un minicab?","options":["Parándolo directamente en la calle","Mediante una reserva previa con un operador autorizado","En cualquier parada de black cabs"],"answer":1,"explanation":"Transport for London distingue los private hire de los black cabs: los primeros deben reservarse previamente con un operador autorizado.","source":"https://tfl.gov.uk/modes/taxis-and-minicabs/what-to-expect-from-your-journey"},{"id":"taxi-05","question":"¿Para qué sirve una rampa en un eurotaxi?","options":["Para aumentar la capacidad del depósito","Para facilitar la entrada y salida de una silla de ruedas","Para reparar un pinchazo"],"answer":1,"explanation":"La rampa facilita el acceso de una persona que viaja en silla de ruedas.","source":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-20785"},{"id":"taxi-06","question":"En un taxi adaptado, ¿qué sujeta el sistema de anclajes de la silla?","options":["El equipaje a la baca","El retrovisor a la puerta","La silla de ruedas al vehículo"],"answer":2,"explanation":"Los anclajes sujetan la silla al vehículo; el cinturón de la persona cumple otra función.","source":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-20785"},{"id":"taxi-07","question":"En un taxi adaptado, ¿para qué sirve el cinturón de seguridad de la persona?","options":["Para sujetar a la persona durante el trayecto","Para sustituir los anclajes de la silla","Para plegar la rampa automáticamente"],"answer":0,"explanation":"El cinturón protege a la persona y no sustituye el sistema de anclaje de la silla.","source":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-20785"},{"id":"taxi-08","question":"Si una persona con discapacidad solicita un taxi, ¿cuál es una buena manera de ofrecer ayuda?","options":["Mover su silla sin consultarle","Preguntar cómo prefiere recibirla","Dirigirse solo a su acompañante"],"answer":1,"explanation":"La guía de Fundación ONCE recomienda preguntar y respetar la forma de ayuda que indique la persona.","source":"https://www.fundaciononce.es/sites/default/files/docs/manual_alcanzar_inclusion%5B1%5D_2.pdf"},{"id":"taxi-09","question":"Al hablar con un pasajero con discapacidad acompañado, ¿a quién conviene dirigirse?","options":["Siempre al acompañante","A una tercera persona por teléfono","Al propio pasajero"],"answer":2,"explanation":"La comunicación directa con el pasajero muestra respeto y facilita que exprese sus necesidades.","source":"https://www.fundaciononce.es/sites/default/files/docs/manual_alcanzar_inclusion%5B1%5D_2.pdf"},{"id":"taxi-10","question":"Si una persona tiene dificultades para oír, ¿qué puede facilitar la comunicación?","options":["Hablarle de frente y dejar visible la boca","Hablar mirando hacia otro lado","Cubrirse la boca mientras se habla"],"answer":0,"explanation":"Mirar a la persona y mantener la boca visible puede facilitar la lectura labial.","source":"https://www.cnse.es/inmigracion/index.php?Itemid=253&id=62&lang=es&option=com_content&view=article"},{"id":"taxi-11","question":"¿Qué alternativa puede ayudar a comunicarse con un pasajero con dificultades auditivas?","options":["Apagar las luces interiores","Escribir la información necesaria","Girar la cara mientras se habla"],"answer":1,"explanation":"La comunicación escrita es una alternativa útil cuando la comunicación oral resulta difícil.","source":"https://www.cnse.es/inmigracion/index.php?Itemid=253&id=62&lang=es&option=com_content&view=article"},{"id":"taxi-12","question":"¿Cómo se conoce popularmente a los taxis tradicionales de Londres?","options":["Yellow boats","Red buses","Black cabs"],"answer":2,"explanation":"Transport for London explica que los taxis londinenses se conocen popularmente como black cabs.","source":"https://tfl.gov.uk/modes/taxis-and-minicabs/what-to-expect-from-your-journey"},{"id":"taxi-13","question":"¿Deben ser necesariamente negros los llamados black cabs de Londres?","options":["No, pueden ser de otros colores","Sí, todos deben ser negros","Solo pueden ser amarillos"],"answer":0,"explanation":"Pese a su nombre, los black cabs londinenses pueden tener otros colores.","source":"https://tfl.gov.uk/modes/taxis-and-minicabs/what-to-expect-from-your-journey"},{"id":"taxi-14","question":"¿Qué nombre recibe el examen de conocimiento de las calles de Londres para taxistas?","options":["The Compass","The Knowledge","The Highway Code"],"answer":1,"explanation":"The Knowledge es la prueba por la que los taxistas londinenses demuestran su conocimiento de la ciudad.","source":"https://tfl.gov.uk/modes/taxis-and-minicabs/what-to-expect-from-your-journey"},{"id":"taxi-15","question":"¿Qué dispositivo de un taxi londinense indica el precio del viaje?","options":["El cuentakilómetros parcial","El reloj del salpicadero","El taxímetro"],"answer":2,"explanation":"Los taxis londinenses utilizan taxímetro para calcular la tarifa.","source":"https://tfl.gov.uk/modes/taxis-and-minicabs/what-to-expect-from-your-journey"},{"id":"taxi-16","question":"¿Qué señal luminosa suele indicar que un taxi londinense está disponible?","options":["La luz de disponible encendida","Las luces de freno encendidas","La luz interior apagada"],"answer":0,"explanation":"Transport for London indica que los black cabs llevan una luz de disponible en el techo.","source":"https://tfl.gov.uk/modes/taxis-and-minicabs/what-to-expect-from-your-journey"},{"id":"taxi-17","question":"¿En qué ciudad se asocian tradicionalmente los taxis autorizados con el color amarillo?","options":["Londres","Nueva York","Venecia"],"answer":1,"explanation":"Nueva York adoptó el amarillo para identificar sus taxis autorizados.","source":"https://www.nyc.gov/html/records/html/newsletter/june2012.html"},{"id":"taxi-18","question":"Según los archivos de Nueva York, ¿en qué año estaban pintados de amarillo todos los taxis con licencia medallion?","options":["1907","1997","1967"],"answer":2,"explanation":"Los archivos municipales señalan que en 1967 todos los taxis medallion estaban pintados de amarillo.","source":"https://www.nyc.gov/html/records/html/newsletter/june2012.html"},{"id":"taxi-19","question":"Según los archivos municipales de Nueva York, ¿cuándo aparecieron allí los taxis con taxímetro?","options":["1907","1967","1987"],"answer":0,"explanation":"Los archivos municipales relacionan la llegada de taxis con taxímetro a Nueva York con 1907.","source":"https://www.nyc.gov/html/records/html/newsletter/june2012.html"},{"id":"taxi-20","question":"Según el manual de la DGT de 2023, ¿qué indica la señal S-18?","options":["Una estación de tren","Una parada de taxis","Un punto de repostaje"],"answer":1,"explanation":"La señal S-18 indica una parada de taxis.","source":"https://www.dgt.es/export/sites/web-DGT/.galleries/downloads/nuestros_servicios/permisos-de-conducir/Accesibilidad/TeoricaAbreviada_LecturaFacil_2023-12_Interactivo.pdf"}],"icon":"map"},{"id":"supervivencia","title":"Naturaleza y supervivencia","heading":"Preparados para la aventura","description":"Orientación, prevención y seguridad en la naturaleza.","questions":[{"id":"supervivencia-01","question":"Antes de una ruta de montaña, ¿qué conviene consultar?","options":["La previsión meteorológica","Solo la distancia sin consultar el tiempo","Solo las horas de luz"],"answer":0,"explanation":"La Guardia Civil recomienda informarse de la previsión antes de salir.","source":"https://web.guardiacivil.es/es/colaboracion/consejos/montana/"},{"id":"supervivencia-02","question":"¿Qué información es útil dejar a una persona de confianza antes de una excursión?","options":["Únicamente el color de la mochila","La ruta prevista y cuándo esperas volver","Solo el nombre del primer pueblo"],"answer":1,"explanation":"Comunicar el itinerario y el regreso previsto ayuda a orientar una búsqueda si surge una emergencia.","source":"https://web.guardiacivil.es/ca/colaboracion/planturismoseguro/que-planes-de-vacaciones-tienes/"},{"id":"supervivencia-03","question":"Al planificar un recorrido en grupo, ¿a qué ritmo conviene ajustar el horario?","options":["Al de la persona más rápida, sin descansos","A un tiempo fijo sin considerar al grupo","Al de la persona más lenta, con margen"],"answer":2,"explanation":"La Guardia Civil aconseja prever un margen adecuado para la persona más lenta.","source":"https://web.guardiacivil.es/es/colaboracion/consejos/montana/"},{"id":"supervivencia-04","question":"¿Qué debe tenerse en cuenta al elegir una ruta de montaña?","options":["La capacidad física y técnica del grupo","Solo la distancia en línea recta","Solo el desnivel de la bajada"],"answer":0,"explanation":"Es prudente elegir una actividad acorde con las capacidades de quienes participan.","source":"https://web.guardiacivil.es/es/colaboracion/consejos/montana/"},{"id":"supervivencia-05","question":"¿Qué aconseja la Guardia Civil sobre salir solo a la montaña?","options":["Salir siempre sin avisar","Evitarlo y procurar ir acompañado","Separarse al empezar para avanzar más rápido"],"answer":1,"explanation":"La Guardia Civil aconseja no ir solo y planificar la actividad en grupo.","source":"https://web.guardiacivil.es/es/colaboracion/consejos/montana/"},{"id":"supervivencia-06","question":"¿Por qué conviene llevar una linterna aunque se espere volver de día?","options":["Porque sustituye el mapa","Porque aumenta la cobertura del móvil","Porque puede haber retrasos o cambios imprevistos"],"answer":2,"explanation":"La Guardia Civil incluye la linterna en el equipo incluso si no se prevé finalizar de noche.","source":"https://web.guardiacivil.es/es/colaboracion/consejos/montana/"},{"id":"supervivencia-07","question":"Antes de salir, ¿cómo conviene llevar la batería del teléfono?","options":["Cargada al máximo","Con media carga sin posibilidad de recarga","Apagada sin comprobar su carga"],"answer":0,"explanation":"La Guardia Civil recomienda llevar teléfono y comprobar que la batería esté totalmente cargada.","source":"https://web.guardiacivil.es/es/colaboracion/consejos/montana/"},{"id":"supervivencia-08","question":"¿Qué equipo para protegerse del frío incluye la Guardia Civil en su lista básica?","options":["Un abanico de papel","Una manta térmica","Un cojín de playa"],"answer":1,"explanation":"La manta térmica forma parte del equipo que la Guardia Civil recomienda llevar.","source":"https://web.guardiacivil.es/es/colaboracion/consejos/montana/"},{"id":"supervivencia-09","question":"Si sufres un accidente en montaña y avisas a emergencias, ¿qué dato ayuda al rescate?","options":["El lugar de salida sin más detalles","El destino previsto sin la posición actual","La localización lo más exacta posible"],"answer":2,"explanation":"Comunicar dónde ha ocurrido y dónde se encuentra la víctima facilita la intervención.","source":"https://web.guardiacivil.es/es/colaboracion/consejos/montana/"},{"id":"supervivencia-10","question":"Además del lugar, ¿qué conviene contar al pedir un rescate?","options":["Qué ha ocurrido y el estado de la víctima","Solo el destino previsto","Solo la hora de salida"],"answer":0,"explanation":"Los equipos de rescate necesitan saber qué ha ocurrido y en qué estado está la víctima.","source":"https://web.guardiacivil.es/es/colaboracion/consejos/montana/"},{"id":"supervivencia-11","question":"¿Qué número gratuito de emergencias funciona en toda la Unión Europea?","options":["118","112","010"],"answer":1,"explanation":"El 112 es el número europeo de emergencias y la llamada es gratuita.","source":"https://europa.eu/youreurope/citizens/travel/security-and-emergencies/emergency/index_es.htm"},{"id":"supervivencia-12","question":"En un mapa topográfico, ¿qué indican curvas de nivel muy juntas?","options":["Una zona necesariamente inundada","Un terreno muy llano","Una pendiente pronunciada"],"answer":2,"explanation":"Cuanto más juntas aparecen las curvas de nivel, más abrupta es la pendiente.","source":"https://educativo.ign.es/atlas-didactico/cartografia-bach/representacin_del_relieve.html"},{"id":"supervivencia-13","question":"En primeros auxilios, ¿qué significa PAS?","options":["Proteger, avisar y socorrer","Parar, andar y saltar","Pedir, apagar y salir"],"answer":0,"explanation":"PAS resume la secuencia de proteger, avisar a emergencias y socorrer según las propias posibilidades.","source":"https://www.cruzroja.es/guiaprevencion/activacion-sistema-emergencia.html"},{"id":"supervivencia-14","question":"En la pauta PAS, ¿qué se hace primero?","options":["Mover siempre a la víctima de inmediato","Proteger para evitar nuevos riesgos","Dejar sola a la víctima sin comprobar riesgos"],"answer":1,"explanation":"Proteger significa valorar los riesgos y evitar que se produzcan más víctimas.","source":"https://www.cruzroja.es/guiaprevencion/activacion-sistema-emergencia.html"},{"id":"supervivencia-15","question":"¿Qué puntos une una curva de nivel en un mapa?","options":["Puntos con la misma temperatura","Puntos de la misma altitud","Puntos con igual población"],"answer":1,"explanation":"Las curvas de nivel unen puntos que tienen la misma altitud respecto a un nivel de referencia.","source":"https://educativo.ign.es/atlas-didactico/cartografia-bach/representacin_del_relieve.html"},{"id":"supervivencia-16","question":"Con mucho calor, ¿en qué momento conviene evitar el ejercicio extenuante al aire libre?","options":["Durante las horas de más calor","Solo al amanecer","Únicamente cuando está nublado"],"answer":0,"explanation":"Cruz Roja recomienda evitar actividades extenuantes durante el momento más caluroso del día.","source":"https://www2.cruzroja.es/enguardiacontraelcalor"},{"id":"supervivencia-17","question":"En una salida con calor, ¿qué ayuda a proteger la cabeza del sol?","options":["Una prenda impermeable para los pies","Una gorra o un sombrero","Un cinturón de tela"],"answer":1,"explanation":"Cruz Roja recomienda sombreros o gorras que protejan la cabeza y el cuello.","source":"https://www2.cruzroja.es/enguardiacontraelcalor"},{"id":"supervivencia-18","question":"¿Qué conviene llevar para hidratarse en una actividad por la naturaleza?","options":["Solo bebidas alcohólicas","Nada, aunque la ruta dure horas","Agua adecuada para la duración prevista"],"answer":2,"explanation":"La Guardia Civil aconseja llevar agua y alimentos adecuados a la duración prevista.","source":"https://web.guardiacivil.es/ca/colaboracion/planturismoseguro/que-planes-de-vacaciones-tienes/"},{"id":"supervivencia-19","question":"Antes de encender fuego en el monte, ¿qué es necesario hacer?","options":["Consultar las normas y restricciones aplicables en la zona","Suponer que está permitido en cualquier época","Decidirlo solo por la temperatura"],"answer":0,"explanation":"Las restricciones dependen del lugar y de la época: consulta siempre las normas vigentes antes de encender fuego.","source":"https://espacios.proteccioncivil.es/es/web/guest/coordinacion/gestion-de-riesgos/incendios-forestales"},{"id":"supervivencia-20","question":"¿Qué organismo emite los avisos meteorológicos que aparecen en el mapa de la Red de Alerta Nacional?","options":["La Dirección General del Catastro","La AEMET","El Instituto de Cinematografía"],"answer":1,"explanation":"El mapa de la Red de Alerta Nacional muestra los avisos meteorológicos emitidos por la AEMET.","source":"https://ran-vmap.proteccioncivil.es/"}],"icon":"pin"},{"id":"taller-chuchi","title":"El taller de Chuchi","heading":"De la tabla a la caja nido","description":"Maderas, ensambles y proyectos para disfrutar del taller.","icon":"cup","questions":[{"id":"chuchi-taller-chuchi-01","question":"¿Qué materia forma la base de un tablero MDF o DM?","options":["Fibras de madera","Virutas orientadas","Chapas de madera superpuestas"],"answer":0,"explanation":"El MDF se fabrica con fibras de madera.","source":"https://www.finsa.com/documents/20121/02bd1fc4-f7ed-4532-64f2-43be665b0729"},{"id":"chuchi-taller-chuchi-02","question":"¿Qué caracteriza a un tablero contrachapado?","options":["Listones macizos unidos por sus cantos","Varias chapas de madera unidas","Partículas de madera prensadas con resina"],"answer":1,"explanation":"El contrachapado reúne láminas finas de madera adheridas entre sí.","source":"https://www.finsa.com/documents/20121/02bd1fc4-f7ed-4532-64f2-43be665b0729"},{"id":"chuchi-taller-chuchi-03","question":"¿Qué se une para fabricar un tablero aglomerado de madera?","options":["Chapas enteras superpuestas","Listones macizos ensamblados","Partículas de madera"],"answer":2,"explanation":"El tablero de partículas aprovecha fragmentos de madera aglomerados.","source":"https://www.finsa.com/documents/20121/02bd1fc4-f7ed-4532-64f2-43be665b0729"},{"id":"chuchi-taller-chuchi-04","question":"¿Qué madera se usa habitualmente para fabricar tubillones?","options":["Haya","Balsa","Teca"],"answer":0,"explanation":"Los tubillones comerciales se elaboran frecuentemente con madera de haya.","source":"https://www.leroymerlin.es/ideas-y-consejos/como-elegir/como-elegir-tubillones-y-espigas.html"},{"id":"chuchi-taller-chuchi-05","question":"Una superficie revestida de chapa natural lleva…","options":["Un papel decorativo impregnado de resina","Una capa de madera auténtica","Un revestimiento de PVC estampado"],"answer":1,"explanation":"La chapa natural conserva el material y el dibujo propios de la madera.","source":"https://www.finsa.com/es/superficiesdecorativasnaturales"},{"id":"chuchi-taller-chuchi-06","question":"¿Por qué una tabla puede cambiar de dimensiones con el ambiente?","options":["Por la oxidación superficial de la madera","Por la cristalización de resina en sus poros","Porque capta o cede humedad"],"answer":2,"explanation":"La madera intercambia humedad con el aire y eso modifica sus dimensiones.","source":"https://www.finsa.com/documents/d/guest/recomendaciones_uso_texturizados"},{"id":"chuchi-taller-chuchi-07","question":"¿Para qué se aclimatan los tableros antes de instalarlos?","options":["Para aproximarlos a las condiciones del lugar","Para endurecer el adhesivo interno del tablero","Para reducir su espesor nominal antes del montaje"],"answer":0,"explanation":"La aclimatación ayuda a reducir movimientos posteriores por cambios de humedad.","source":"https://www.finsa.com/documents/d/guest/recomendaciones_uso_texturizados"},{"id":"chuchi-taller-chuchi-08","question":"¿Qué forma tiene un tubillón corriente?","options":["Una lámina plana ovalada","Un cilindro pequeño","Una cuña trapezoidal"],"answer":1,"explanation":"Este pequeño cilindro conecta dos piezas mediante orificios enfrentados.","source":"https://www.leroymerlin.es/ideas-y-consejos/como-elegir/como-elegir-tubillones-y-espigas.html"},{"id":"chuchi-taller-chuchi-09","question":"¿Para qué sirven las estrías de muchos tubillones?","options":["Para formar una rosca que agarre la madera","Para graduar la profundidad de inserción","Para repartir la cola y facilitar su salida"],"answer":2,"explanation":"Los canales favorecen el contacto con el adhesivo y la salida de su exceso.","source":"https://www.leroymerlin.es/ideas-y-consejos/como-elegir/como-elegir-tubillones-y-espigas.html"},{"id":"chuchi-taller-chuchi-10","question":"¿Qué facilita el extremo biselado de un tubillón?","options":["Su entrada en el orificio","La expansión lateral de la espiga al encolar","El bloqueo de la pieza al girarla"],"answer":0,"explanation":"El extremo algo más estrecho ayuda a presentar la pieza en el agujero.","source":"https://www.leroymerlin.es/ideas-y-consejos/como-elegir/como-elegir-tubillones-y-espigas.html"},{"id":"chuchi-taller-chuchi-11","question":"En ensamblajes de madera, ¿qué son las galletas?","options":["Pequeños cilindros de madera estriados","Pequeñas piezas planas ovaladas","Cuñas trapezoidales talladas en un extremo"],"answer":1,"explanation":"Las galletas se alojan en ranuras para unir las piezas.","source":"https://www.leroymerlin.es/ideas-y-consejos/como-elegir/como-elegir-tubillones-y-espigas.html"},{"id":"chuchi-taller-chuchi-12","question":"En una unión de caja y espiga, ¿qué elemento sobresale?","options":["La caja","El galce","La espiga"],"answer":2,"explanation":"La parte saliente entra en el hueco complementario de la otra pieza.","source":"https://tesauros.cultura.gob.es/tesauros/mobiliario/1174046.html"},{"id":"chuchi-taller-chuchi-13","question":"¿Qué dos formas encajan en una unión machihembrada?","options":["Una ranura y una lengüeta","Dos rebajes a media madera","Una cola trapezoidal y su alojamiento"],"answer":0,"explanation":"El resalte longitudinal de una pieza se introduce en el canal de otra.","source":"https://tesauros.cultura.gob.es/tesauros/tecnicas/1006596.html?desplegar=1148867889&replegar="},{"id":"chuchi-taller-chuchi-14","question":"Para una esquina de marco a inglete de 90°, ¿cómo suelen cortarse los extremos?","options":["A 30° cada uno","A 45° cada uno","A 60° cada uno"],"answer":1,"explanation":"Dos cortes de 45° permiten cerrar esa esquina del marco.","source":"https://tesauros.cultura.gob.es/tesauros/mobiliario/1174068.html?desplegar=1932366184&replegar="},{"id":"chuchi-taller-chuchi-15","question":"¿Qué forma caracteriza al ensamble llamado cola de milano?","options":["Rectangular","Cilíndrica","Trapezoidal"],"answer":2,"explanation":"Su perfil se ensancha como un trapecio y encaja con una forma complementaria.","source":"https://tesauros.cultura.gob.es/tesauros/mobiliario/1173988.html"},{"id":"chuchi-taller-chuchi-16","question":"Al diseñar una caja nido, ¿por qué importa el tamaño de la entrada?","options":["Porque influye en qué aves pueden usarla","Porque determina el número de puestas de la pareja","Porque permite prescindir del drenaje de la base"],"answer":0,"explanation":"El diámetro de entrada debe corresponder a las especies a las que se destina.","source":"https://tienda.seo.org/aves-de-jardin/cajas-nido/?product_orderby=name&product_view=list"},{"id":"chuchi-taller-chuchi-17","question":"¿Qué facilita una puerta practicable en una caja nido?","options":["La salida habitual de las aves por una segunda entrada","Revisarla y limpiarla cuando corresponde","La ventilación permanente dejándola abierta durante la cría"],"answer":1,"explanation":"Una parte que se abre permite acceder al interior para su mantenimiento.","source":"https://tienda.seo.org/aves-de-jardin/cajas-nido/?product_orderby=name&product_view=list"},{"id":"chuchi-taller-chuchi-18","question":"¿Para qué sirven pequeños orificios en la base de una caja nido?","options":["Para mantener sujetos los materiales del nido","Para fijar perchas en el interior","Para drenar el agua"],"answer":2,"explanation":"Los agujeros de drenaje ayudan a evitar que se acumule agua dentro.","source":"https://www.ecoescuelas.org/sites/default/files/2023-09/Cajas_Nido.pdf"},{"id":"chuchi-taller-chuchi-19","question":"¿Por qué conviene que el interior de una caja nido no quede demasiado liso?","options":["Para que las aves puedan trepar mejor","Para impedir que la madera absorba agua","Para eliminar la necesidad de ventilación"],"answer":0,"explanation":"La textura de la madera ofrece apoyo a las aves al desplazarse.","source":"https://www.ecoescuelas.org/sites/default/files/2023-09/Cajas_Nido.pdf"},{"id":"chuchi-taller-chuchi-20","question":"¿Cuándo se programa la limpieza habitual de una caja nido?","options":["Durante la incubación","Fuera del periodo de cría y sin ocupantes","Justo cuando nacen los pollos"],"answer":1,"explanation":"El mantenimiento debe respetar la reproducción y comprobar que la caja está desocupada.","source":"https://seo.org/mesdelosnidos-cuidados-y-mantenimiento-de-la-caja-nido/"}]},{"id":"aves-estaciones","title":"Aves durante el año","heading":"Un año mirando al cielo","description":"Invernantes, migraciones y cambios en las aves que nos rodean.","icon":"sprout","questions":[{"id":"chuchi-aves-estaciones-01","question":"¿En qué estación pasan muchas grullas europeas varios meses en España?","options":["En invierno","En verano","En primavera"],"answer":0,"explanation":"Muchas grullas europeas pasan la época fría en la península ibérica.","source":"https://seo.org/ave/grulla-comun/"},{"id":"chuchi-aves-estaciones-02","question":"¿Dónde es habitual que se alimenten las grullas durante la invernada peninsular?","options":["En bosques densos de montaña","En dehesas y cultivos","En playas y acantilados costeros"],"answer":1,"explanation":"Dehesas, arrozales y campos ofrecen recursos a las bandadas invernantes.","source":"https://seo.org/ave/grulla-comun/"},{"id":"chuchi-aves-estaciones-03","question":"Al caer la tarde, ¿adónde suelen dirigirse las bandadas de grullas?","options":["A territorios separados para pasar la noche","A colonias de nidos para incubar","A dormideros compartidos"],"answer":2,"explanation":"Se reúnen para descansar en lugares tranquilos, a menudo ligados al agua.","source":"https://seo.org/ave/grulla-comun/"},{"id":"chuchi-aves-estaciones-04","question":"¿Qué alimento aprovechan muchas grullas en las dehesas durante parte del invierno?","options":["Bellotas","Piñones","Corteza de encina"],"answer":0,"explanation":"Las bellotas son un recurso importante antes de que aumente el consumo de otros alimentos.","source":"https://seo.org/ave/grulla-comun/"},{"id":"chuchi-aves-estaciones-05","question":"¿Qué sucede con los milanos reales de España durante el invierno?","options":["Se inicia su principal periodo de reproducción","Se suman aves llegadas de otros países europeos","Los reproductores españoles se marchan al África tropical"],"answer":1,"explanation":"A los residentes se añaden numerosos invernantes del resto de Europa.","source":"https://seo.org/ave/milano-real/"},{"id":"chuchi-aves-estaciones-06","question":"¿Qué agrupación forman muchos milanos reales para pasar las noches de invierno?","options":["Parejas aisladas en nidos de cría","Colonias reproductoras en cortados","Dormideros comunales"],"answer":2,"explanation":"Los bosquetes y sotos pueden reunir muchos individuos al anochecer.","source":"https://seo.org/ave/milano-real/"},{"id":"chuchi-aves-estaciones-07","question":"¿Qué ambiente suelen recorrer los milanos reales invernantes buscando alimento?","options":["Campiñas y zonas abiertas","Carrizales inundados","Playas intermareales"],"answer":0,"explanation":"Los campos despejados facilitan que localicen recursos durante el día.","source":"https://seo.org/ave/milano-real/"},{"id":"chuchi-aves-estaciones-08","question":"¿En qué región pasan el invierno muchas golondrinas comunes que crían en España?","options":["En el valle del Nilo","En el golfo de Guinea","En las costas del Magreb"],"answer":1,"explanation":"La guía de SEO sitúa su invernada principalmente en esa región africana.","source":"https://seo.org/ave/golondrina-comun/"},{"id":"chuchi-aves-estaciones-09","question":"¿Por qué no basta una única fecha para anunciar la llegada de las golondrinas a toda España?","options":["Porque permanecen ocultas hasta completar la muda","Porque el regreso principal ocurre después de la cría","Porque varía mucho entre regiones"],"answer":2,"explanation":"La llegada al sur puede adelantarse mucho a la observada en el norte.","source":"https://seo.org/ave/golondrina-comun/"},{"id":"chuchi-aves-estaciones-10","question":"En otoño, algunas golondrinas que vemos de paso por España…","options":["Proceden de otras zonas de Europa","Se dirigen a España para iniciar la cría","Van hacia sus áreas de cría del norte de Europa"],"answer":0,"explanation":"La Península también forma parte de las rutas de otras poblaciones europeas.","source":"https://seo.org/ave/golondrina-comun/"},{"id":"chuchi-aves-estaciones-11","question":"¿Cómo se describe habitualmente la presencia del vencejo común en España?","options":["Invernante, con cría en el norte de Europa","Estival, con migración de larga distancia","Residente, con desplazamientos solo locales"],"answer":1,"explanation":"Su temporada habitual aquí es la de cría, aunque existen observaciones invernales ocasionales.","source":"https://seo.org/ave/vencejo-comun/"},{"id":"chuchi-aves-estaciones-12","question":"¿Hacia dónde migran los vencejos comunes para pasar la época no reproductora?","options":["Hacia el Magreb y el sur de Europa","Hacia el Cáucaso y el mar Caspio","Hacia África al sur del ecuador"],"answer":2,"explanation":"Sus áreas de invernada se encuentran en el África subsahariana meridional.","source":"https://seo.org/ave/vencejo-comun/"},{"id":"chuchi-aves-estaciones-13","question":"¿Qué afirmación es correcta sobre las cigüeñas blancas en invierno en España?","options":["Algunas permanecen sin cruzar a África","La invernada se limita a Canarias y Baleares","Solo se quedan ejemplares procedentes de Centroeuropa"],"answer":0,"explanation":"La especie combina movimientos migratorios con una creciente invernada en España.","source":"https://seo.org/ave/ciguena-blanca/"},{"id":"chuchi-aves-estaciones-14","question":"¿Qué paso utilizan muchas cigüeñas que viajan entre la Península y África?","options":["El estrecho del Bósforo","El estrecho de Gibraltar","El estrecho de Mesina"],"answer":1,"explanation":"Gibraltar concentra el paso de numerosas cigüeñas de distintas poblaciones.","source":"https://seo.org/ave/ciguena-blanca/"},{"id":"chuchi-aves-estaciones-15","question":"¿Qué movimiento hacen con frecuencia los petirrojos de bosques de montaña al llegar el frío?","options":["Se concentran por encima del límite del bosque","Se desplazan hacia los bosques del norte de Europa","Descienden a zonas más bajas"],"answer":2,"explanation":"El descenso de altitud es uno de sus movimientos invernales habituales.","source":"https://seo.org/ave/petirrojo-europeo/"},{"id":"chuchi-aves-estaciones-16","question":"En otoño e invierno, ¿con qué pueden complementar su dieta los petirrojos?","options":["Frutos de arbustos","Bellotas enteras","Acículas de coníferas"],"answer":0,"explanation":"A los pequeños invertebrados pueden añadir frutos de zarzas y otros arbustos.","source":"https://seo.org/ave/petirrojo-europeo/"},{"id":"chuchi-aves-estaciones-17","question":"¿Qué anota una persona que participa en Aves y Clima?","options":["Las medidas de anillas recuperadas","Fechas de observaciones estacionales","La composición química de las plumas"],"answer":1,"explanation":"Las llegadas, salidas y otros acontecimientos permiten seguir el calendario natural.","source":"https://seo.org/avesyclima/"},{"id":"chuchi-aves-estaciones-18","question":"¿Qué aporta observar un mismo lugar de forma regular a lo largo de los años?","options":["Estimar la edad exacta de individuos sin marcar","Reconstruir la ruta de cada ave vista una sola vez","Comparar cuándo ocurren los cambios estacionales"],"answer":2,"explanation":"La continuidad de las observaciones ayuda a detectar adelantos y retrasos.","source":"https://seo.org/avesyclima/"},{"id":"chuchi-aves-estaciones-19","question":"Para colaborar en Aves y Clima, ¿qué resulta útil?","options":["Reconocer especies habituales y registrar sus fechas","Registrar solo el número de nidos, sin fechas","Anotar solo aves raras y omitir las comunes"],"answer":0,"explanation":"El programa permite participar a personas que conocen aves comunes de su entorno.","source":"https://seo.org/avesyclima/"},{"id":"chuchi-aves-estaciones-20","question":"¿Qué ayuda a conocer el seguimiento de aves con dispositivos de localización?","options":["El parentesco genético entre dos ejemplares","Sus rutas y lugares de parada","La composición exacta de su dieta"],"answer":1,"explanation":"El seguimiento permite estudiar desplazamientos, escalas y áreas de invernada.","source":"https://seo.org/monografias-de-migracion/"}]},{"id":"salamanca-taxi","title":"Salamanca desde el taxi","heading":"La ciudad que llevamos en la cabeza","description":"Calles, barrios y lugares para reconocer Salamanca.","icon":"map","questions":[{"id":"chuchi-salamanca-taxi-01","question":"Un pasajero quiere ir a la estación principal de tren. ¿Qué vía corresponde a su dirección?","options":["Paseo de la Estación","Avenida de Filiberto Villalobos","Paseo de San Vicente"],"answer":0,"explanation":"Adif sitúa la estación de Salamanca en el paseo de la Estación.","source":"https://www.adif.es/w/30100-salamanca"},{"id":"chuchi-salamanca-taxi-02","question":"¿Qué une Vialia Salamanca en un mismo recinto?","options":["La estación de autobuses y un mercado de abastos","La estación ferroviaria y espacios comerciales","Un recinto de ferias y un centro deportivo"],"answer":1,"explanation":"Vialia integra el servicio ferroviario con comercios y ocio.","source":"https://www.adif.es/w/salamanca"},{"id":"chuchi-salamanca-taxi-03","question":"¿Qué apeadero salmantino menciona Adif cerca del centro?","options":["Tejares","El Arrabal","La Alamedilla"],"answer":2,"explanation":"La Alamedilla es el apeadero urbano al que alude la ficha de Vialia.","source":"https://www.adif.es/w/salamanca"},{"id":"chuchi-salamanca-taxi-04","question":"Te piden los cines Van Dyck de Salamanca. ¿Qué paseo figura en su dirección?","options":["Torres Villarroel","Carmelitas","San Vicente"],"answer":0,"explanation":"Las salas indican el paseo del Doctor Torres Villarroel como dirección.","source":"https://www.salamanca.cinesvandyck.com/preguntas-frecuentes"},{"id":"chuchi-salamanca-taxi-05","question":"¿Qué barrio salmantino se ha convertido en una galería de arte urbano al aire libre?","options":["San Bernardo","El barrio del Oeste","Garrido"],"answer":1,"explanation":"La iniciativa vecinal Zoes ha impulsado allí murales y otras intervenciones.","source":"https://salamanca.es/agenda/visitas/paseo-por-la-galeria-urbana-barrio-del-oeste"},{"id":"chuchi-salamanca-taxi-06","question":"¿Qué plaza actúa como centro de la Galería Urbana del barrio del Oeste?","options":["La plaza de los Bandos","La plaza de la Concordia","La plaza del Oeste"],"answer":2,"explanation":"El proyecto parte de ese espacio y se extiende por las calles del barrio.","source":"https://salamanca.es/es/destacados/item/download/312_1291f3f1977b45473ae5ca51392178d8"},{"id":"chuchi-salamanca-taxi-07","question":"¿En qué calle está la entrada de la Casa de las Conchas?","options":["Compañía","Rosario","Toro"],"answer":0,"explanation":"La dirección de la Casa de las Conchas es calle Compañía, 2.","source":"https://www.salamanca.es/que-ver/monumentos/casa-de-las-conchas"},{"id":"chuchi-salamanca-taxi-08","question":"Si alguien quiere subir a Scala Coeli, ¿qué torres busca?","options":["Las de las catedrales","Las de la Clerecía","Las del Palacio de Monterrey"],"answer":1,"explanation":"Scala Coeli recorre las torres de la iglesia de la Clerecía.","source":"https://www.salamanca.es/que-ver/monumentos/scala-coeli"},{"id":"chuchi-salamanca-taxi-09","question":"¿Qué conjunto monumental se recorre por las alturas con Ieronimus?","options":["La Clerecía","El Palacio de Monterrey","Las catedrales"],"answer":2,"explanation":"Ieronimus es la visita a las torres de las catedrales salmantinas.","source":"https://www.salamanca.es/que-ver/monumentos/scala-coeli"},{"id":"chuchi-salamanca-taxi-10","question":"Un visitante pide el Museo de Art Nouveau y Art Déco. ¿Qué edificio busca?","options":["La Casa Lis","La Casa de las Conchas","El Palacio de Anaya"],"answer":0,"explanation":"La Casa Lis alberga las colecciones de artes decorativas de esos estilos.","source":"https://www.salamanca.es/que-ver/museo/museo-de-art-nouveau-y-art-deco-casa-lis"},{"id":"chuchi-salamanca-taxi-11","question":"¿En qué calle se encuentra la entrada de la Casa Lis?","options":["San Pablo","Gibraltar","Tentenecio"],"answer":1,"explanation":"La fachada de acceso y la dirección del museo dan a la calle Gibraltar.","source":"https://www.salamanca.es/que-ver/museo/museo-de-art-nouveau-y-art-deco-casa-lis"},{"id":"chuchi-salamanca-taxi-12","question":"¿Qué río cruza el Puente Romano de Salamanca?","options":["El Águeda","El Alagón","El Tormes"],"answer":2,"explanation":"El puente forma parte del paisaje histórico de las riberas del Tormes.","source":"https://www.salamanca.es/que-ver/monumentos/puente-romano"},{"id":"chuchi-salamanca-taxi-13","question":"¿Con qué antigua vía se relaciona el Puente Romano salmantino?","options":["La Vía de la Plata","El Camino Francés","La Vía Augusta"],"answer":0,"explanation":"El paso sobre el Tormes se integraba en la ruta de la Vía de la Plata.","source":"https://www.salamanca.es/que-ver/monumentos/puente-romano"},{"id":"chuchi-salamanca-taxi-14","question":"¿Qué jardín recuerda en su nombre a los amantes de La Celestina?","options":["El Campo de San Francisco","El Huerto de Calixto y Melibea","El parque de La Alamedilla"],"answer":1,"explanation":"El nombre del huerto evoca a los protagonistas de la obra de Fernando de Rojas.","source":"https://salamanca.es/que-ver/monumentos/huerto-de-calixto-y-melibea"},{"id":"chuchi-salamanca-taxi-15","question":"¿Qué plaza aparece en la dirección del convento de San Esteban?","options":["Plaza de Colón","Plaza de Anaya","Concilio de Trento"],"answer":2,"explanation":"El convento de los dominicos se encuentra en la plaza del Concilio de Trento.","source":"https://www.salamanca.es/que-ver/monumentos/convento-de-san-esteban"},{"id":"chuchi-salamanca-taxi-16","question":"¿Qué edificio preside el lado norte de la Plaza Mayor?","options":["El Ayuntamiento","El Pabellón Real","El Pabellón de San Martín"],"answer":0,"explanation":"La fachada de la Casa Consistorial ocupa ese lado de la plaza.","source":"https://www.salamanca.es/que-ver/monumentos/plaza-mayor"},{"id":"chuchi-salamanca-taxi-17","question":"¿Qué piedra da su característico tono dorado a la Plaza Mayor?","options":["El granito de Los Santos","La piedra de Villamayor","La piedra caliza de Campaspero"],"answer":1,"explanation":"La arenisca de Villamayor es el material principal del conjunto.","source":"https://www.salamanca.es/que-ver/monumentos/plaza-mayor"},{"id":"chuchi-salamanca-taxi-18","question":"¿Qué puente de estructura de hierro aparece junto al entorno histórico del Tormes?","options":["El Puente Romano","El puente de la Universidad","El puente de Enrique Estevan"],"answer":2,"explanation":"El puente de Enrique Estevan es un hito de hierro del siglo XX.","source":"https://www.salamanca.es/que-ver/monumentos/puente-romano"},{"id":"chuchi-salamanca-taxi-19","question":"Un pasajero menciona el santuario de la Virgen de la Salud. ¿Con qué barrio se asocia?","options":["Tejares","Pizarrales","Garrido"],"answer":0,"explanation":"La parroquia de San Pedro y el santuario de la Virgen de la Salud están en Tejares.","source":"https://www.diocesisdesalamanca.com/noticias/el-barrio-de-tejares-inicia-el-novenario-a-la-virgen-de-la-salud/"},{"id":"chuchi-salamanca-taxi-20","question":"Si paseas junto al Tormes, ¿qué árboles son propios de su vegetación de ribera?","options":["Encinas, alcornoques y quejigos","Chopos, fresnos y sauces","Pinos, enebros y sabinas"],"answer":1,"explanation":"El soto fluvial proporciona refugio a aves entre esos árboles de ribera.","source":"https://www.salamanca.es/que-ver/naturaleza/ribera-del-rio-tormes"}]}];
